//! Kotlin bindings for the offline signer (UniFFI). The Kotlin file is
//! generated by the separate tool in `tools/uniffi-bindgen` (see
//! docs/signer-app.md). Thin wrappers only: all
//! logic and checks live in `signer-core`.
//!
//! Secrets stay inside Rust objects (`Seed`, `UnlockedWallet`) wherever
//! possible. The one exception is `Seed::words()`, which must reach the
//! screen once so the user can write the recovery phrase down.

#![allow(clippy::unwrap_used)] // generated scaffolding

use std::sync::Arc;

use signer_core::policy::{self, Asset, Net, Payment, Policy, PolicyError};
use signer_core::{
    accounts, attestation, btc_sign, entropy, eth_sign, export, seed, tron_sign, vault,
};
use wallet_types::{Tier, WalletId};
use zeroize::Zeroizing;

uniffi::setup_scaffolding!();

#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum SignerError {
    #[error("{msg}")]
    Dice { msg: String },
    #[error("{msg}")]
    Seed { msg: String },
    #[error("{msg}")]
    Vault { msg: String },
    #[error("{msg}")]
    Export { msg: String },
    #[error("{msg}")]
    Input { msg: String },
    #[error("{msg}")]
    Sign { msg: String },
}

fn sign_err(e: btc_sign::SignError) -> SignerError {
    SignerError::Sign { msg: e.to_string() }
}

fn policy_err(e: PolicyError) -> SignerError {
    match e {
        PolicyError::Invalid(msg) => SignerError::Input { msg },
        e => SignerError::Sign { msg: e.to_string() },
    }
}

fn seed_err(e: seed::SeedError) -> SignerError {
    SignerError::Seed { msg: e.to_string() }
}

/// Public data of a wallet (shown and exported; never secret).
#[derive(Debug, Clone, uniffi::Record)]
pub struct WalletPublicRecord {
    pub fingerprint: String,
    pub btc_zpub: String,
    pub eth: String,
    pub tron: String,
}

impl From<accounts::WalletPublic> for WalletPublicRecord {
    fn from(p: accounts::WalletPublic) -> Self {
        Self {
            fingerprint: p.fingerprint,
            btc_zpub: p.btc_zpub,
            eth: p.eth,
            tron: p.tron,
        }
    }
}

impl From<WalletPublicRecord> for accounts::WalletPublic {
    fn from(p: WalletPublicRecord) -> Self {
        Self {
            fingerprint: p.fingerprint,
            btc_zpub: p.btc_zpub,
            eth: p.eth,
            tron: p.tron,
        }
    }
}

fn parse_tier(t: &str) -> Result<Tier, SignerError> {
    Ok(match t {
        "vault" => Tier::Vault,
        "savings" => Tier::Savings,
        "spending" => Tier::Spending,
        _ => {
            return Err(SignerError::Input {
                msg: "unknown tier".into(),
            })
        }
    })
}

fn parse_id(id: &str) -> Result<WalletId, SignerError> {
    id.parse()
        .map_err(|e: wallet_types::InvalidWalletId| SignerError::Input { msg: e.to_string() })
}

/// Number of valid dice rolls typed so far, or why they're not acceptable yet.
#[uniffi::export]
pub fn check_dice(rolls: String) -> Result<u32, SignerError> {
    let rolls = Zeroizing::new(rolls);
    let parsed =
        entropy::parse_dice(&rolls).map_err(|e| SignerError::Dice { msg: e.to_string() })?;
    Ok(u32::try_from(parsed.len()).unwrap_or(u32::MAX))
}

/// A seed held inside Rust. Dropping it wipes the entropy.
#[derive(uniffi::Object)]
pub struct Seed {
    inner: seed::SeedMaterial,
}

/// Create a new 24-word seed: OS randomness mixed with the dice rolls.
#[uniffi::export]
pub fn new_seed(dice_rolls: String) -> Result<Arc<Seed>, SignerError> {
    let rolls = Zeroizing::new(dice_rolls);
    let dice = entropy::parse_dice(&rolls).map_err(|e| SignerError::Dice { msg: e.to_string() })?;
    let ent = entropy::new_entropy(&dice).map_err(|_| SignerError::Seed {
        msg: "random generator failed".into(),
    })?;
    Ok(Arc::new(Seed {
        inner: seed::SeedMaterial::from_entropy(&ent),
    }))
}

/// Restore a seed from its 12 or 24 words, one word per entry (word #1
/// first). The error names the word number that is wrong.
#[uniffi::export]
pub fn restore_seed(words: Vec<String>) -> Result<Arc<Seed>, SignerError> {
    let words = Zeroizing::new(words);
    Ok(Arc::new(Seed {
        inner: seed::SeedMaterial::from_word_list(&words).map_err(seed_err)?,
    }))
}

#[uniffi::export]
impl Seed {
    /// The recovery words, to be written on paper once. Don't keep them.
    pub fn words(&self) -> Result<Vec<String>, SignerError> {
        Ok(self.inner.words().map_err(seed_err)?.to_vec())
    }

    /// Random word positions (1-based) the user must type back.
    pub fn word_check_positions(&self, count: u32) -> Result<Vec<u32>, SignerError> {
        let total = self.inner.words().map_err(seed_err)?.len();
        let pos =
            seed::word_check_positions(total, count as usize).map_err(|_| SignerError::Seed {
                msg: "random generator failed".into(),
            })?;
        Ok(pos
            .into_iter()
            .map(|p| u32::try_from(p).unwrap_or(0))
            .collect())
    }

    pub fn check_words(
        &self,
        positions: Vec<u32>,
        answers: Vec<String>,
    ) -> Result<bool, SignerError> {
        let pos: Vec<usize> = positions.into_iter().map(|p| p as usize).collect();
        seed::check_words(&self.inner, &pos, &answers).map_err(seed_err)
    }

    /// Public data for this seed + passphrase ("" for none).
    pub fn derive_public(&self, passphrase: String) -> Result<WalletPublicRecord, SignerError> {
        let passphrase = Zeroizing::new(passphrase);
        Ok(accounts::derive_public(&self.inner, &passphrase)
            .map_err(seed_err)?
            .into())
    }

    /// Encrypt this seed into a vault file (Spending/Savings only).
    pub fn seal_vault(
        &self,
        id: String,
        label: String,
        tier: String,
        public: WalletPublicRecord,
        uses_passphrase: bool,
        vault_password: String,
    ) -> Result<Vec<u8>, SignerError> {
        let vault_password = Zeroizing::new(vault_password);
        let kdf = vault::signer_kdf().map_err(|e| SignerError::Vault { msg: e.to_string() })?;
        let info = vault::WalletInfo {
            id: parse_id(&id)?,
            label,
            tier: parse_tier(&tier)?,
            public: public.into(),
            uses_passphrase,
        };
        vault::create(&info, &self.inner, &vault_password, kdf)
            .map_err(|e| SignerError::Vault { msg: e.to_string() })
    }
}

/// An unlocked stored wallet (for one signing session; drop it afterwards).
/// Holds the passphrase too (wiped on drop), because signing needs it.
#[derive(uniffi::Object)]
pub struct UnlockedWallet {
    inner: vault::UnlockedWallet,
    passphrase: Zeroizing<String>,
}

impl UnlockedWallet {
    fn master(&self) -> Result<bitcoin::bip32::Xpriv, SignerError> {
        let pass: &str = if self.inner.uses_passphrase {
            &self.passphrase
        } else {
            ""
        };
        self.inner.seed.master(pass).map_err(seed_err)
    }

    /// Open this wallet's signing policy (sealed with a key from its seed).
    fn policy(
        &self,
        bytes: Option<Vec<u8>>,
        now_ms: u64,
    ) -> Result<(Policy, [u8; 32]), SignerError> {
        let key = policy::mac_key(&self.master()?);
        let p = Policy::open(bytes.as_deref(), &key, &self.inner.id.to_string(), now_ms)
            .map_err(policy_err)?;
        Ok((p, key))
    }
}

/// A signature to show to the PC, plus the updated policy file. The app
/// must save `policy` before it shows `qr_text`.
#[derive(Debug, Clone, uniffi::Record)]
pub struct SignedRecord {
    pub qr_text: String,
    pub policy: Vec<u8>,
    /// This signature's number in the tablet's signing log.
    pub seq: u64,
}

#[derive(Debug, Clone, uniffi::Record)]
pub struct AllowedAddressRecord {
    pub net: String,
    pub net_name: String,
    pub address: String,
    pub label: String,
    /// 0 when usable; otherwise when it becomes usable (tablet clock, ms).
    pub usable_from_ms: u64,
}

#[derive(Debug, Clone, uniffi::Record)]
pub struct LimitRecord {
    pub asset: String,
    pub name: String,
    pub unit: String,
    pub daily: String,
    /// Signed in the last 24 hours.
    pub used_day: String,
    pub pending: Option<String>,
    pub pending_from_ms: u64,
}

#[derive(Debug, Clone, uniffi::Record)]
pub struct LogRecord {
    pub seq: u64,
    pub time_ms: u64,
    pub asset: String,
    pub recipient: String,
    pub amount: String,
    pub unit: String,
    pub txid: String,
}

#[derive(Debug, Clone, uniffi::Record)]
pub struct PolicyRecord {
    pub addresses: Vec<AllowedAddressRecord>,
    pub limits: Vec<LimitRecord>,
    /// Newest first (at most 50).
    pub recent: Vec<LogRecord>,
    pub signed_total: u64,
    pub head: String,
}

impl From<policy::PolicyView> for PolicyRecord {
    fn from(v: policy::PolicyView) -> Self {
        Self {
            addresses: v
                .addresses
                .into_iter()
                .map(|a| AllowedAddressRecord {
                    net: a.net,
                    net_name: a.net_name,
                    address: a.address,
                    label: a.label,
                    usable_from_ms: a.usable_from_ms,
                })
                .collect(),
            limits: v
                .limits
                .into_iter()
                .map(|l| LimitRecord {
                    asset: l.asset,
                    name: l.name,
                    unit: l.unit,
                    daily: l.daily,
                    used_day: l.used_24h,
                    pending: l.pending,
                    pending_from_ms: l.pending_from_ms,
                })
                .collect(),
            recent: v
                .recent
                .into_iter()
                .map(|e| LogRecord {
                    seq: e.seq,
                    time_ms: e.time_ms,
                    asset: e.asset,
                    recipient: e.recipient,
                    amount: e.amount,
                    unit: e.unit,
                    txid: e.txid,
                })
                .collect(),
            signed_total: v.signed_total,
            head: v.head,
        }
    }
}

/// A network the allowlist can hold addresses for.
#[derive(Debug, Clone, uniffi::Record)]
pub struct NetRecord {
    pub code: String,
    pub name: String,
}

#[uniffi::export]
pub fn policy_networks() -> Vec<NetRecord> {
    Net::ALL
        .into_iter()
        .map(|n| NetRecord {
            code: n.code().into(),
            name: n.name().into(),
        })
        .collect()
}

